  const int lm = lane >> 2;
  const int ln = lane & 3;
  const int row0 = (wm << 6) + (lm << 3);
  const int col0 = (wn << 5) + (ln << 3);
  T acc[TM][TN];
  #pragma unroll
  for (int i = 0; i < TM; ++i)
    #pragma unroll
    for (int j = 0; j < TN; ++j)
      acc[i][j] = T(0);
  // 16B-aligned vectorized global loads require row strides that are
  // multiples of 4 floats.
  const bool kvec = ((K & 3) == 0);
  const bool nvec = ((N & 3) == 0);
  for (int k0 = 0; k0 < K; k0 += BK) {
    // Stage A tile transposed (sA: BK x BM). Vectorized path: each thread
    // loads one float4 (4 consecutive k for one row m) from global memory,
    // then scatters it into the transposed smem layout.
    if (kvec) {
      #pragma unroll
      for (int it = 0; it < (BM * (BK / 4)) / THREADS; ++it) {
        int p  = tid + it * THREADS;
        int m  = p / (BK / 4);
        int c  = p % (BK / 4);
        int gm = m0 + m;
        int gk = k0 + 4 * c;
        float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
        if (gm < M && gk < K)
          v = *reinterpret_cast<const float4*>(A + (int64_t)gm * K + gk);
        smemA[(4 * c + 0) * SA + m] = v.x;
        smemA[(4 * c + 1) * SA + m] = v.y;
        smemA[(4 * c + 2) * SA + m] = v.z;
        smemA[(4 * c + 3) * SA + m] = v.w;
      }
    } else {
      for (int idx = tid; idx < BM * BK; idx += THREADS) {
        int m  = idx / BK;
        int k  = idx % BK;
        int gm = m0 + m;
        int gk = k0 + k;
        T v = (gm < M && gk < K) ? mA(gm, gk) : T(0);
        smemA[k * SA + m] = v;
      }
    }
    // Stage B tile (BK x BN). Vectorized path: each thread performs one
    // coalesced float4 global load and one aligned float4 smem store.
    if (nvec) {
      #pragma unroll
      for (int it = 0; it < (BK * (BN / 4)) / THREADS; ++it) {
        int p  = tid + it * THREADS;
        int k  = p / (BN / 4);
        int c  = p % (BN / 4);
        int gk = k0 + k;
        int gn = n0 + 4 * c;
        float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
        if (gk < K && gn < N)
          v = *reinterpret_cast<const float4*>(B + (int64_t)gk * N + gn);
        *reinterpret_cast<float4*>(&smemB[k * SB + 4 * c]) = v;
      }
    } else {
      for (int idx = tid; idx < BK * BN; idx += THREADS) {
        int k  = idx / BN;
        int n  = idx % BN;
        int gk = k0 + k;
        int gn = n0 + n;
        T v = (gk < K && gn < N) ? mB(gk, gn) : T(0);
        smemB[k * SB + n] = v;
      }
    }
    __syncthreads();
    // Each thread accumulates a contiguous 8x8 sub-tile: rows {ty*8 + i}
    // and columns {tx*8 + j}. The contiguous 8-row / 8-column ownership
    // together with the transposed sA layout lets both fragments be read
    // as two float4 loads per k step (4 LDS.128 vs 16 LDS.32 before),
    // while keeping the aligned float4 global stores in the epilogue.
    #pragma unroll
    for (int k = 0; k < BK; ++k) {
      const float4* a4 =
          reinterpret_cast<const float4*>(&smemA[k * SA + row0]);
      const float4* b4 =
          reinterpret_cast<const float4*>(&smemB[k * SB + col0]);
      float4 a0 = a4[0];
      float4 a1 = a4[1];
      float4 b0 = b4[0];
      float4 b1 = b4[1];
      T rA[TM] = {a0.x, a0.y, a0.z, a0.w, a1.x, a1.y, a1.z, a1.w};
      T rB[TN] = {b0.x, b0.y, b0.z, b0.w, b1.x, b1.y, b1.z, b1.w};
      #pragma unroll
      for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
          acc[i][j] += rA[i] * rB[j];
    }
    __syncthreads();
  }
  // Epilogue: store contiguous 8-column chunks. When the row stride keeps
  // rows 16B aligned, emit two streaming (evict-first) float4 stores per
  // row (st.global.cs): the huge C output is write-only, so bypassing the
  // L2 write-back policy avoids cache pollution and increases effective
  // store bandwidth; otherwise fall back to scalar stores.
  const bool vec4_ok = ((N & 3) == 0);
  #pragma unroll
  for (int i = 0; i < TM; ++i) {
    int gm = m0 + row0 + i;
    if (gm >= M) continue;
    int gn = n0 + col0;
    if (vec4_ok && gn + 7 < N) {
      float4* out4 = reinterpret_cast<float4*>(C + (int64_t)gm * N + gn);
      __stcs(&out4[0], make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]));
      __stcs(&out4[1], make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]));
    } else {
      #pragma unroll
      for (int j = 0; j < TN; ++j) {
        int c = gn + j;
        if (c < N) mC(gm, c) = acc[i][j];
      }
    }
  }
}

// Specialized tall-skinny kernel: the contraction dimension K is tiny
// (K <= 32), so the whole K-slab is kept inside the CTA (BK = 32 >= K).
// The CTA tiles only the two large output dims (M, N); the single A/B
// slab is staged once (one __syncthreads, no k-loop, no loop-carried
// syncs, no per-tile k bounds checks) and the K reduction is fully
// unrolled in registers. Avoids split-K / square-GEMM overhead.
template <typename T>
__global__ void gemm_smallk_kernel(const T* __restrict__ A,
                                   const T* __restrict__ B,
                                   T* __restrict__ C,
                                   int M, int N, int K)
{
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 32;  // K <= 32: entire contraction fits in one tile
  constexpr int TM = 16;
  constexpr int TN = 4;
  constexpr int THREADS = (BM / TM) * (BN / TN);  // 256
  constexpr int TX = BN / TN;                     // 32
  constexpr int TY = BM / TM;                     // 8
  constexpr int SA = BM + 4;  // sA row stride (132), sA is BK x BM
  constexpr int SB = BN + 4;  // sB row stride (132), sB is BK x BN
  const int tid = threadIdx.x;
  const int tiles_n = (N + BN - 1) / BN;
  const int tile = blockIdx.x;
  const int by  = tile / tiles_n;
  const int bx  = tile - by * tiles_n;
  __shared__ __align__(16) T smemA[BK * SA];
  __shared__ __align__(16) T smemB[BK * SB];
  const int m0 = by * BM;
  const int n0 = bx * BN;
  // Warp-coalesced mapping: one warp owns a 16-row by 128-column slab.
  // For each output row, the 32 lanes store 32 consecutive float4s, so
  // every st.global.cs is a fully covered 128B sector instead of two
  // interleaved half-sector stores from an 8-column thread tile.
  const int row0 = (tid / TX) * TM;
  const int col0 = (tid % TX) * TN;
  T acc[TM][TN];
  #pragma unroll
  for (int i = 0; i < TM; ++i)
    #pragma unroll
    for (int j = 0; j < TN; ++j)
      acc[i][j] = T(0);
  const bool kvec = ((K & 3) == 0);
  const bool nvec = ((N & 3) == 0);
  // Single-stage load of the only K-slab (zero-padded where k >= K).
  if (kvec) {
    #pragma unroll
    for (int it = 0; it < (BM * (BK / 4)) / THREADS; ++it) {
      int p  = tid + it * THREADS;
      int m  = p / (BK / 4);
      int c  = p % (BK / 4);
      int gm = m0 + m;
      int gk = 4 * c;
      float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
      if (gm < M && gk < K)
        v = *reinterpret_cast<const float4*>(A + (int64_t)gm * K + gk);
      smemA[(4 * c + 0) * SA + m] = v.x;
      smemA[(4 * c + 1) * SA + m] = v.y;
      smemA[(4 * c + 2) * SA + m] = v.z;
      smemA[(4 * c + 3) * SA + m] = v.w;
    }
  } else {
    for (int idx = tid; idx < BM * BK; idx += THREADS) {
      int m  = idx / BK;
      int k  = idx % BK;
      int gm = m0 + m;
      T v = (gm < M && k < K) ? A[(int64_t)gm * K + k] : T(0);
      smemA[k * SA + m] = v;
    }
  }
  if (nvec) {
    #pragma unroll
    for (int it = 0; it < (BK * (BN / 4)) / THREADS; ++it) {
      int p  = tid + it * THREADS;
      int k  = p / (BN / 4);
      int c  = p % (BN / 4);
      int gn = n0 + 4 * c;
      float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
      if (k < K && gn < N)
        v = *reinterpret_cast<const float4*>(B + (int64_t)k * N + gn);
      *reinterpret_cast<float4*>(&smemB[k * SB + 4 * c]) = v;
    }
  } else {
    for (int idx = tid; idx < BK * BN; idx += THREADS) {
      int k  = idx / BN;
      int n  = idx % BN;
      int gn = n0 + n;
      T v = (k < K && gn < N) ? B[(int64_t)k * N + gn] : T(0);
      smemB[k * SB + n] = v;
    }
  }
  __syncthreads();
  // Fully unrolled reduction over the whole (small) K held in the CTA.
  #pragma unroll
  for (int k = 0; k < BK; ++k) {
    const float4* a4 =
          reinterpret_cast<const float4*>(&smemA[k * SA + row0]);
    const float4* b4 =
          reinterpret_cast<const float4*>(&smemB[k * SB + col0]);
    float4 a0 = a4[0];
    float4 a1 = a4[1];
    float4 a2 = a4[2];
    float4 a3 = a4[3];
    float4 b0 = b4[0];
    T rA[TM] = {a0.x, a0.y, a0.z, a0.w,
                a1.x, a1.y, a1.z, a1.w,
                a2.x, a2.y, a2.z, a2.w,
                a3.x, a3.y, a3.z, a3.w};
    T rB[TN] = {b0.x, b0.y, b0.z, b0.w};
    #pragma unroll
    for (int i = 0; i < TM; ++i)
      #pragma unroll
      for (int j = 0; j < TN; ++j)
        acc[i][j] += rA[i] * rB[j];
  }
  // Epilogue: one aligned float4 store per row per lane; lanes in a warp
  // cover a contiguous 128-float output row segment for this CTA tile.
  const bool vec4_ok = ((N & 3) == 0);
  #pragma unroll
  for (int i = 0; i < TM; ++i) {
    int gm = m0 + row0 + i;
    if (gm >= M) continue;
    int gn = n0 + col0;
    if (vec4_ok && gn + 3 < N) {
      float4* out4 = reinterpret_cast<float4*>(C + (int64_t)gm * N + gn);
      __stcs(&out4[0], make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]));
    } else {
      #pragma unroll
      for (int j = 0; j < TN; ++j) {
        int c = gn + j;
        if (c < N) C[(int64_t)gm * N + c] = acc[i][j];
      }
    }
  }
}
torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  const int64_t M = A_c.size(0);
  const int64_t K = A_c.size(1);
  const int64_t N = B_c.size(1);

  auto C = torch::empty({M, N}, A.options());
  if (C.numel() == 0) return C;

  constexpr int BM = 128;
  constexpr int BN = 128;

  const int64_t tiles_m = (M + BM - 1) / BM;
  const int64_t tiles_n = (N + BN - 1) / BN;
  dim3 block(256);
  dim3 grid((unsigned)(tiles_m * tiles_n));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (K <= 32) {
    // Tall-skinny fast path: the whole contraction dim fits in one CTA tile.
    gemm_smallk_kernel<float><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>(),
        (int)M, (int)N, (int)K);
  } else {
    gemm_nn_kernel<float><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>(),
        (int)M, (int)N, (int)K);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ",
              cudaGetErrorString(err));

  return C;
}
